680	 \subsection{Combining the $X$ and $Z$ measurements}
681	\label{sec:combining}
682	
683	In this section our goal is to create a set of combined measurements
684	that simultaneously measure the approximately-commuting measurements
685	constructed in the previous section. We do this first for the points.
686	Recall that $\mH_\alice$ and $\mH_\bob$ denote the Hilbert spaces corresponding to
687	registers $\alice$ and $\bob$, respectively.
688	
689	\begin{lemma}\label{lem:qld-4-10}
690	There exists a function $\delta_Q(\eps) = \poly(\eps)$ such that the following holds. 
691		For every $x,z \in \F_q^m$ and $\mH \in \{ \mH_\alice, \mH_\bob\}$ there are projective measurements $\{ \hat{Q}^{x,z}_{a,b} \}_{a,b \in \F_q}$ acting on $\mathcal{H} \otimes (\C^q)^{\otimes \nqubits}$ such that:
692		\begin{enumerate}
693			\item (\textbf{Self-consistency}) On average over uniformly random $x,z \in \F_q^m$,
694			\begin{equation}
695				\label{eq:qld-q-self-cons}
696				(\hat{Q}^{x,z}_{a,b})_{\alice \alice'}  \approx_{\delta_Q} (\hat{Q}^{x,z}_{a,b})_{\bob \alice''}\,.
697			\end{equation}
698			
699			\item (\textbf{Consistency with $\hat{M}$}) On average over uniformly random $x,z \in \F_q^m$,
700			\begin{gather}
701				\label{eq:qld-q-cons-m-hat-xz}
702					(\hat{Q}^{x,z}_{a,b})_{\alice \alice'} \approx_{\delta_Q} (\hat{M}^{(\Point,X),x}_{a} \hat{M}^{(\Point,Z),z}_b)_{\bob \alice''}\;, \\
703								\label{eq:qld-q-cons-m-hat-zx}
704					(\hat{Q}^{x,z}_{a,b})_{\alice \alice'} \approx_{\delta_Q} (\hat{M}^{(\Point,Z),z}_b  \hat{M}^{(\Point,X),x}_{a} )_{\bob \alice''}\;.
705			\end{gather}
706	              \end{enumerate}
707	                    Furthermore, all symmetric equivalents of these approximations
708	      also hold.
709	\end{lemma}
710	
711	The construction of the measurements $\{ \hat{Q}^{x,z}_{a,b} \}$ whose existence is guaranteed in the lemma proceeds in three steps. In the first step, for every $(r,s)\in\F_q^2$ we combine the binary-outcome measurements $\hat{M}^{(\Point,X),x,r}_a$ and $\hat{M}^{(\Point,X),z,s}_b$; this is made possible by their approximate commutation as shown in Lemma~\ref{lem:qld-comm-cons}. In a second step, we show that the measurements thus constructed have a particular ``approximate linearity'' property, when seen as a function of the pair $(r,s)$. This allows us, in the third step, to combine them into a single measurement $\{ \hat{Q}^{x,z}_{a,b} \}$ with outcomes in $\F_q^2\cong \F_2^{2t}$ by applying the following  result from~\cite{NV17}:
712		
713		\begin{theorem}[Quantum linearity test]
714		\label{thm:linearity}
715			Let $0 \leq \delta \leq 1$, let $t$ be a positive integer, and let $\ket{\psi}$ be a state in a Hilbert space $\mathcal{H}_\alice \otimes \mathcal{H}_\bob$. Let $\{\mathcal{O}^u \}$ be a set of observables indexed by $u \in \F_2^t$ that act on $\mathcal{H}_\alice$. Suppose that on average over $u, u'$ chosen uniformly from $\F_2^t$, we have the following ``approximate linearity'' holds:

348			\tau^W_{[g_h(u)=a]} = \sum_{h \,:\, g_h(u) = a} \tau^W_h\;,
349		\end{equation}
350		together with the analogous identity for $V_{\mathrm{A}}$ on registers $\mathrm{A}\mathrm{A}'\mathrm{A}''$.
351	\end{lemma}
352	\begin{proof}
353		\uses{lem:qld-4-7, lem:tildew-product-form, lem:twisted-commutation, def:v-swap-unitary, def:tilde-m-measurement, def:tau-dot-product-projector, def:indicator-vector, def:decoding-map, def:generalized-pauli}
354		Since the measurement $\{\hat{S}_{g_X,g_Z}\}$ is projective (Lemma~\ref{lem:qld-4-7}) and the $\tau^X, \tau^Z$ observables are self-inverse,
355		\[
356			V_{\mathrm{A}} V_{\mathrm{A}}^\dagger = \sum_{g_X,g_Z} (\hat{S}_{g_X,g_Z})_{\mathrm{A}\mathrm{A}'} \ot \Id_{\mathrm{A}''} = \Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''}\;,
357		\]
358		and the same computation gives $V_{\mathrm{A}}^\dagger V_{\mathrm{A}} = \Id$, so $V_{\mathrm{A}}$ is unitary; likewise $V_{\mathrm{B}}$. For \eqref{eq:v-swap-obs-conjugation}, conjugate the product form \eqref{eq:tildewj-product-form} of $\tilde{W}^j(\tilde{u})$ (Lemma~\ref{lem:tildew-product-form}): by the orthogonality of the projectors $\hat{S}_{g_X,g_Z}$, only the diagonal terms survive, and the twisted commutation relation (Lemma~\ref{lem:twisted-commutation})
359		\[
360			\tau^X(\mathrm{Dec}(g_Z)) \, \tau^Z(\mathrm{Dec}(g_X)) \, \tau^W(e_j \tilde{u}) = (-1)^{\tr( e_j(\mathrm{Dec}(g_W) \cdot \tilde{u}))} \, \tau^W(e_j \tilde{u}) \, \tau^X(\mathrm{Dec}(g_Z)) \, \tau^Z(\mathrm{Dec}(g_X))
361		\]
362		cancels the sign $(-1)^{\tr(e_j (\mathrm{Dec}(g_W) \cdot \tilde{u}))}$ term by term, leaving $\sum_{g_X,g_Z} \hat{S}_{g_X,g_Z} \ot \tau^W(e_j \tilde{u}) = \Id \ot \tau^W(e_j \tilde{u})$. For \eqref{eq:qld-unitary-6}, expand $\tilde{M}^{W,\mathrm{ind}_m(u)}_a$ by \eqref{eq:tilde_M} and \eqref{eq:def-tauwu}; by the orthogonality of the $\hat{S}_{g_X,g_Z}$, conjugation replaces, in the term of $\hat{S}^W_g$, each projector $\tau^W_h$ by $\tau^W_{h + \mathrm{Dec}(g)}$, using the identities $\tau^X(s)\, \tau^Z_h \,\tau^X(s)^\dagger = \tau^Z_{h+s}$ and $\tau^Z(s)\, \tau^X_h\, \tau^Z(s)^\dagger = \tau^X_{h+s}$. Substituting $h' = h + \mathrm{Dec}(g)$ turns the constraint $h \cdot \mathrm{ind}_m(u) = (\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u)) - a$ into $h' \cdot \mathrm{ind}_m(u) = -a = a$, since $\F_q$ has characteristic $2$; the quantity $\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u)$ cancels exactly, so no relation between it and $g(u)$ is used (Remark~\ref{rem:qld-decoding-identity}). Since $h' \cdot \mathrm{ind}_m(u) = g_{h'}(u)$ \eqref{eq:low-degree-encoding-definition}, summing over $g$ gives \eqref{eq:qld-unitary-6}; the computation for $V_{\mathrm{A}}$ on registers $\mathrm{A}\mathrm{A}'\mathrm{A}''$ is identical.
363	\end{proof}
